// Some portions generated by Codex
import type { LabelGuidance } from "./label-policy.ts";
import { Icon } from "./icons.tsx";

export function LabelGuidanceNotice({ reasons, onConfigure, onDismiss }: {
  reasons: readonly LabelGuidance[];
  onConfigure: () => void;
  onDismiss: () => void;
}) {
  if (!reasons.length) return null;
  return <section className="label-guidance" aria-label="Label preference guidance">
    <p>{reasons.map(reason => reason.text).join(" ")}</p>
    <div className="label-guidance-actions">
      <button type="button" className="workbench-action workbench-action--ghost" onClick={onConfigure}>
        Configure labels
      </button>
      <button type="button" className="workbench-action workbench-action--ghost workbench-action--icon"
        aria-label="Dismiss label guidance" title="Dismiss label guidance for this repository" onClick={onDismiss}>
        <Icon name="close" />
      </button>
    </div>
  </section>;
}
